WITH filtered AS (SELECT id, session_id, event_type, event_time, duration_sec, CASE WHEN event_type = 'purchase' THEN 1 ELSE 0 END is_purchase, DATE_FORMAT(event_time, 'MMM yyyy') event_time_label FROM web_events WHERE page IS NOT NULL AND duration_sec < 255), with_prev AS (SELECT *, LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) AS prev_event_time FROM filtered), gaps AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS is_new_session FROM with_prev), sessions_web_events AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT CASE WHEN is_purchase >= 70 THEN 'LARGE' ELSE 'SMALL' END AS is_purchase_tier, CASE WHEN session_no >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END AS session_no_tier, COUNT_IF(event_type = 'search') AS search_events, ROUND(AVG(is_purchase), 2) AS avg_is_purchase, ROUND(AVG(session_no), 2) AS avg_session_no, COUNT(*) FILTER (WHERE event_type = 'purchase') AS purchase_rows, ROUND(SUM(duration_sec) / NULLIF(COUNT(CASE WHEN event_type = 'page_view' THEN 1 END), 0), 2) AS duration_sec_per_page_view FROM sessions_web_events GROUP BY is_purchase_tier, session_no_tier HAVING search_events > 1 ORDER BY avg_session_no DESC
